-- Purchase receiving functions already applied to live Supabase.
CREATE OR REPLACE FUNCTION public.receive_purchase_scan_with_invoice(p_purchase_order_id uuid,p_supplier_invoice_id uuid,p_gtin text,p_quantity integer,p_expiry_date date,p_batch_id text DEFAULT NULL,p_invoice_unit_cost numeric DEFAULT NULL,p_notes text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $fn$
DECLARE v_po public.purchase_orders%rowtype;v_inv public.supplier_invoices%rowtype;v_item public.purchase_order_items%rowtype;v_receipt_id uuid;v_receipt_item_id uuid;v_product_id uuid;v_gtin text;v_before int;v_after int;v_qty int;v_remaining int;v_invoice_price numeric;v_price_var numeric;v_receipt_no text;
BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin authorization required';END IF;v_qty:=COALESCE(p_quantity,0);IF v_qty<=0 THEN RAISE EXCEPTION 'Received quantity must be greater than zero';END IF;IF p_expiry_date IS NULL THEN RAISE EXCEPTION 'Expiry date is required';END IF;SELECT * INTO v_po FROM public.purchase_orders WHERE id=p_purchase_order_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found';END IF;SELECT * INTO v_inv FROM public.supplier_invoices WHERE id=p_supplier_invoice_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Supplier invoice not found';END IF;IF v_inv.supplier_id<>v_po.supplier_id THEN RAISE EXCEPTION 'Invoice supplier does not match purchase order supplier';END IF;SELECT poi.* INTO v_item FROM public.purchase_order_items poi JOIN public.products p ON p.id=poi.product_id WHERE poi.purchase_order_id=p_purchase_order_id AND NULLIF(trim(p_gtin),'') IS NOT NULL AND (p.gtin=trim(p_gtin) OR poi.gtin=trim(p_gtin)) ORDER BY poi.id LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'GTIN % is not on purchase order %',p_gtin,v_po.po_number;END IF;v_remaining:=GREATEST(v_item.quantity_ordered-v_item.quantity_received,0);IF v_qty>v_remaining THEN RAISE EXCEPTION 'Received quantity % exceeds remaining PO quantity %',v_qty,v_remaining;END IF;SELECT p.id,p.gtin INTO v_product_id,v_gtin FROM public.products p WHERE p.id=v_item.product_id;v_receipt_no:='GRN-'||to_char(now(),'YYYYMMDD-HH24MISS')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,5));INSERT INTO public.purchase_receipts(purchase_order_id,supplier_id,supplier_invoice_id,receipt_number,status,created_by,notes) VALUES(v_po.id,v_po.supplier_id,v_inv.id,v_receipt_no,'received',auth.uid(),p_notes) RETURNING id INTO v_receipt_id;v_invoice_price:=COALESCE(p_invoice_unit_cost,v_item.unit_cost);v_price_var:=v_invoice_price-v_item.unit_cost;INSERT INTO public.purchase_receipt_items(receipt_id,purchase_order_item_id,product_id,gtin,quantity_received,unit_cost,invoice_unit_cost,quantity_variance,price_variance,notes) VALUES(v_receipt_id,v_item.id,v_product_id,COALESCE(NULLIF(trim(p_gtin),''),v_gtin),v_qty,v_item.unit_cost,p_invoice_unit_cost,v_qty-v_remaining,v_price_var,p_notes) RETURNING id INTO v_receipt_item_id;INSERT INTO public.purchase_receipt_batches(receipt_item_id,product_id,batch_id,expiry_date,quantity) VALUES(v_receipt_item_id,v_product_id,p_batch_id,p_expiry_date,v_qty);INSERT INTO public.product_expiry(product_id,batch_id,expiry_date,quantity) VALUES(v_product_id,p_batch_id,p_expiry_date,v_qty);SELECT stock_quantity INTO v_before FROM public.central_inventory WHERE product_id=v_product_id FOR UPDATE;IF NOT FOUND THEN INSERT INTO public.central_inventory(product_id,stock_quantity,reserved_quantity,product_name) SELECT v_product_id,0,0,name FROM public.products WHERE id=v_product_id;v_before:=0;END IF;UPDATE public.central_inventory SET stock_quantity=stock_quantity+v_qty,updated_at=now() WHERE product_id=v_product_id;SELECT stock_quantity INTO v_after FROM public.central_inventory WHERE product_id=v_product_id;INSERT INTO public.inventory_logs(product_id,change,reference_id,reference_number,reference_type,old_quantity,new_quantity,type,movement_type,reason,notes,edited_by,created_at) VALUES(v_product_id,v_qty,v_receipt_id,v_receipt_no,'PURCHASE_RECEIPT',v_before,v_after,'RECEIPT','PURCHASE','Supplier receipt',COALESCE(p_notes,'PO receipt'),auth.uid(),now());UPDATE public.purchase_order_items SET quantity_received=quantity_received+v_qty WHERE id=v_item.id;INSERT INTO public.supplier_invoice_items(invoice_id,purchase_order_item_id,product_id,product_name,supplier_sku,gtin,quantity,received_quantity,quantity_invoiced,unit_cost,agreed_price,invoiced_price,pack_size,packs,line_total,variance_quantity,variance_unit_cost,variance_total,discrepancy_found,is_verified)SELECT v_inv.id,v_item.id,v_product_id,p.name,v_item.supplier_sku,v_gtin,v_qty,v_qty,v_qty,v_invoice_price,v_item.unit_cost,v_invoice_price,GREATEST(v_item.pack_size,1),CEIL(v_qty::numeric/GREATEST(v_item.pack_size,1)),v_qty*v_invoice_price,v_qty-v_remaining,v_price_var,v_qty*v_price_var,abs(v_price_var)>0.0001,true FROM public.products p WHERE p.id=v_product_id;UPDATE public.supplier_invoices SET purchase_order_id=v_po.id,status='received',subtotal=(SELECT COALESCE(sum(line_total),0) FROM public.supplier_invoice_items WHERE invoice_id=v_inv.id),total_amount=(SELECT COALESCE(sum(line_total),0) FROM public.supplier_invoice_items WHERE invoice_id=v_inv.id)+COALESCE(v_inv.tax_amount,0)+COALESCE(v_inv.shipping_cost,0),updated_at=now() WHERE id=v_inv.id;UPDATE public.purchase_orders po SET actual_delivery_date=COALESCE(po.actual_delivery_date,CURRENT_DATE),status=CASE WHEN NOT EXISTS(SELECT 1 FROM public.purchase_order_items q WHERE q.purchase_order_id=po.id AND q.quantity_received<q.quantity_ordered) THEN 'received' ELSE 'partially_received' END,updated_at=now() WHERE po.id=p_purchase_order_id;RETURN jsonb_build_object('receipt_id',v_receipt_id,'receipt_item_id',v_receipt_item_id,'po_item_id',v_item.id,'product_id',v_product_id,'product_gtin',v_gtin,'quantity_received',v_qty,'po_remaining_after',v_remaining-v_qty,'old_stock',v_before,'new_stock',v_after,'invoice_unit_cost',v_invoice_price,'price_variance',v_price_var,'invoice_id',v_inv.id);END;$fn$;
CREATE OR REPLACE FUNCTION public.reconcile_purchase(p_purchase_order_id uuid,p_supplier_invoice_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $fn$
DECLARE v_id uuid;v_receipt uuid;v_po_qty int;v_recv_qty int;v_inv_qty int;v_po_total numeric;v_recv_total numeric;v_inv_total numeric;v_qty_var int;v_price_var numeric;v_total_var numeric;v_details jsonb;
BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin authorization required';END IF;SELECT id INTO v_receipt FROM public.purchase_receipts WHERE purchase_order_id=p_purchase_order_id AND status<>'cancelled' ORDER BY received_at DESC LIMIT 1;SELECT COALESCE(sum(quantity_ordered),0),COALESCE(sum(total),0) INTO v_po_qty,v_po_total FROM public.purchase_order_items WHERE purchase_order_id=p_purchase_order_id;SELECT COALESCE(sum(pri.quantity_received),0),COALESCE(sum(pri.quantity_received*pri.unit_cost),0) INTO v_recv_qty,v_recv_total FROM public.purchase_receipts pr JOIN public.purchase_receipt_items pri ON pri.receipt_id=pr.id WHERE pr.purchase_order_id=p_purchase_order_id AND pr.status<>'cancelled';IF p_supplier_invoice_id IS NULL THEN v_inv_qty:=0;v_inv_total:=0;ELSE SELECT COALESCE(sum(COALESCE(quantity_invoiced,quantity)),0),COALESCE(sum(line_total),0) INTO v_inv_qty,v_inv_total FROM public.supplier_invoice_items WHERE invoice_id=p_supplier_invoice_id;END IF;v_qty_var:=CASE WHEN p_supplier_invoice_id IS NULL THEN v_recv_qty-v_po_qty ELSE v_recv_qty-v_inv_qty END;v_price_var:=CASE WHEN p_supplier_invoice_id IS NULL THEN v_recv_total-v_po_total ELSE v_inv_total-v_po_total END;v_total_var:=CASE WHEN p_supplier_invoice_id IS NULL THEN v_recv_total-v_po_total ELSE v_inv_total-v_recv_total END;v_details:=jsonb_build_object('po_vs_received_quantity',v_recv_qty-v_po_qty,'po_vs_invoice_quantity',CASE WHEN p_supplier_invoice_id IS NULL THEN NULL ELSE v_inv_qty-v_po_qty END,'received_vs_invoice_quantity',CASE WHEN p_supplier_invoice_id IS NULL THEN NULL ELSE v_inv_qty-v_recv_qty END,'po_vs_invoice_total',CASE WHEN p_supplier_invoice_id IS NULL THEN NULL ELSE v_inv_total-v_po_total END,'received_vs_invoice_total',CASE WHEN p_supplier_invoice_id IS NULL THEN NULL ELSE v_inv_total-v_recv_total END);SELECT id INTO v_id FROM public.purchase_reconciliations WHERE purchase_order_id=p_purchase_order_id AND ((supplier_invoice_id=p_supplier_invoice_id) OR(supplier_invoice_id IS NULL AND p_supplier_invoice_id IS NULL)) ORDER BY updated_at DESC LIMIT 1;IF v_id IS NULL THEN INSERT INTO public.purchase_reconciliations(purchase_order_id,supplier_invoice_id,purchase_receipt_id,status,po_quantity,received_quantity,invoiced_quantity,po_total,received_total,invoice_total,quantity_variance,price_variance,total_variance,variance_details)VALUES(p_purchase_order_id,p_supplier_invoice_id,v_receipt,CASE WHEN p_supplier_invoice_id IS NULL AND v_recv_qty=v_po_qty THEN 'matched' WHEN p_supplier_invoice_id IS NOT NULL AND v_recv_qty=v_inv_qty AND abs(v_inv_total-v_po_total)<0.01 THEN 'matched' ELSE 'discrepancy' END,v_po_qty,v_recv_qty,v_inv_qty,v_po_total,v_recv_total,v_inv_total,v_qty_var,v_price_var,v_total_var,v_details)RETURNING id INTO v_id;ELSE UPDATE public.purchase_reconciliations SET purchase_receipt_id=v_receipt,status=CASE WHEN p_supplier_invoice_id IS NULL AND v_recv_qty=v_po_qty THEN 'matched' WHEN p_supplier_invoice_id IS NOT NULL AND v_recv_qty=v_inv_qty AND abs(v_inv_total-v_po_total)<0.01 THEN 'matched' ELSE 'discrepancy' END,po_quantity=v_po_qty,received_quantity=v_recv_qty,invoiced_quantity=v_inv_qty,po_total=v_po_total,received_total=v_recv_total,invoice_total=v_inv_total,quantity_variance=v_qty_var,price_variance=v_price_var,total_variance=v_total_var,variance_details=v_details,updated_at=now() WHERE id=v_id;END IF;RETURN v_id;END;$fn$;
GRANT EXECUTE ON FUNCTION public.receive_purchase_scan_with_invoice(uuid,uuid,text,integer,date,text,numeric,text) TO authenticated;GRANT EXECUTE ON FUNCTION public.reconcile_purchase(uuid,uuid) TO authenticated;